'use strict';
/* =====================================================================
   Pumpkin add-on  (load AFTER letter.js)
   ---------------------------------------------------------------------
   1. when the prize is revealed (#scratch gets "cleared") wait 5 seconds
   2. the scratch card slides up and out, the coin fades, the pumpkin slides in from the bottom
   3. CARVE IT: draw any shape with your finger / mouse on the pumpkin (a circle, a triangle, a smile ...).
      When you let go the shape is closed and the part of the pumpkin inside it is cut out:
      it gets a light-orange cut edge, drops out and tumbles off the bottom of the screen,
      and the pumpkin keeps a hole in that spot. Carve as many shapes as you like (eyes, nose, mouth ...).
   The pumpkin + shadow pictures are embedded, so no image files are needed.
   letter.js / letter.css are NOT touched.
   ===================================================================== */
(() => {
  const WAIT_MS = 5000;                        // how long the prize stays visible before the swap
  const HOLE = '#2b1a14';                      // colour seen inside a carved hole (use 'transparent' to see straight through instead)
  const FLESH = '#ffcf8a', RIM = '#3a2a22';    // light-orange cut face and its thin dark outline
  const FLESH_W = 7, RIM_W = 1.7;              // widths (measured on a 440px pumpkin; they scale with its size)
  const rm = matchMedia('(prefers-reduced-motion:reduce)').matches;
  const IMG_PUMPKIN = 'data:image/png;base64,', IMG_SHADOW = 'data:image/png;base64,';

  /* ---------- styles ---------- */
  const st = document.createElement('style');
  st.textContent = `
  .scratch.out .swrap{translate:0 -125vh;transition:translate .95s cubic-bezier(.65,0,.35,1)}
  .coin.free.gone{opacity:0;pointer-events:none;transition:opacity .4s,scale .5s}

  .pumpkin{position:fixed;inset:0;z-index:600;display:grid;place-items:center;visibility:hidden;pointer-events:none;touch-action:none;cursor:crosshair;-webkit-user-select:none;user-select:none}
  .pumpkin.show{visibility:visible;pointer-events:auto}
  .pslide{display:flex;flex-direction:column;align-items:center;gap:18px;translate:0 115vh;transition:translate 1.05s cubic-bezier(.22,1,.36,1) .8s}
  .pumpkin.show .pslide{translate:0 0}
  .pstage{position:relative;width:min(440px,88vw,62vh);aspect-ratio:1}
  .pshadow{position:absolute;inset:0;background:var(--ps) center/100% 100% no-repeat}
  .pstage canvas{position:absolute;display:block;pointer-events:none}
  .pcv{inset:0;width:100%;height:100%}
  .pfall{will-change:transform}
  .phint{margin:0;min-height:1.4em;font:500 15px var(--font);color:var(--ink2);opacity:0;transition:opacity .5s 1.8s}
  .pumpkin.show .phint{opacity:1}
  .pumpkin .phint.hide{opacity:0;transition-delay:0s}
  .ptrail{position:fixed;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}
  .ptrail .t{fill:none;stroke-linecap:round;stroke-linejoin:round;opacity:0;transition:opacity .4s}
  .ptrail .t.on{opacity:1;transition:none}
  #pglow{stroke:#ff8a4c;stroke-width:10;filter:drop-shadow(0 0 8px rgba(255,138,76,.95)) drop-shadow(0 0 18px rgba(255,170,100,.8))}
  #pline{stroke:#fff;stroke-width:3}
  #pclose{stroke:#ff8a4c;stroke-width:3;stroke-dasharray:2 8;opacity:0}
  #pclose.on{opacity:.7}
  @media(prefers-reduced-motion:reduce){.pslide,.phint,.scratch.out .swrap{transition:none}}
  `;
  document.head.appendChild(st);

  /* ---------- markup ---------- */
  const sec = document.createElement('section');
  sec.className = 'pumpkin'; sec.setAttribute('aria-label', 'Pumpkin. Draw a shape on it to carve it out.');
  sec.innerHTML = '<div class="pslide"><div class="pstage" id="pstage"><div class="pshadow"></div></div><p class="phint" id="phint">Draw a shape on the pumpkin to carve it out</p></div>' +
    '<svg class="ptrail" aria-hidden="true"><polyline class="t" id="pglow"/><polyline class="t" id="pline"/><line class="t" id="pclose"/></svg>';
  document.body.appendChild(sec);

  const stage = sec.querySelector('#pstage'), hint = sec.querySelector('#phint');
  const glow = sec.querySelector('#pglow'), line = sec.querySelector('#pline'), closeL = sec.querySelector('#pclose');
  const scratchEl = document.getElementById('scratch'), coinEl = document.getElementById('coin');
  stage.style.setProperty('--ps', 'url(' + IMG_SHADOW + ')');

  /* ---------- canvases: "inner" (dark inside of holes) sits under "main" (the pumpkin skin) ---------- */
  let L = 440, dpr = 1, k = 1, inner, innerX, main, mainX, tmp, tmpX, total = 1, imgOk = false, built = false;
  const im = new Image();
  im.onload = () => { imgOk = true; paintMain(); };
  im.src = IMG_PUMPKIN;

  const mk = cls => {
    const c = document.createElement('canvas'); c.width = c.height = Math.round(L * dpr);
    const x = c.getContext('2d'); x.scale(dpr, dpr);
    if (cls) { c.className = 'pcv ' + cls; stage.appendChild(c); }
    return [c, x];
  };
  function build() {
    if (built) return; built = true;
    L = Math.round(stage.getBoundingClientRect().width) || 440; dpr = Math.min(2, window.devicePixelRatio || 1); k = L / 440;
    [inner, innerX] = mk('pinner'); [main, mainX] = mk('pmain'); [tmp, tmpX] = mk('');
    paintMain();
  }
  function paintMain() {
    if (!built || !imgOk) return;
    mainX.clearRect(0, 0, L, L); mainX.drawImage(im, 0, 0, L, L);
    try {
      const d = mainX.getImageData(0, 0, main.width, main.height).data; let n = 0;
      for (let i = 3; i < d.length; i += 16) if (d[i] > 128) n++;
      total = Math.max(1, n * 4);               // estimated number of pumpkin pixels
    } catch (e) { total = 1; }
  }

  /* a closed, smoothed outline through the drawn points */
  function trace(c, pts) {
    const n = pts.length; c.beginPath();
    c.moveTo((pts[0][0] + pts[n - 1][0]) / 2, (pts[0][1] + pts[n - 1][1]) / 2);
    for (let i = 0; i < n; i++) { const a = pts[i], b = pts[(i + 1) % n]; c.quadraticCurveTo(a[0], a[1], (a[0] + b[0]) / 2, (a[1] + b[1]) / 2); }
    c.closePath();
  }
  function rim(c, pts) {                         // light-orange cut face + thin dark outline, only on pixels that already exist
    c.save(); c.globalCompositeOperation = 'source-atop'; c.lineJoin = c.lineCap = 'round';
    trace(c, pts); c.strokeStyle = FLESH; c.lineWidth = FLESH_W * k * 2; c.stroke();
    trace(c, pts); c.strokeStyle = RIM; c.lineWidth = RIM_W * k * 2; c.stroke();
    c.restore();
  }

  /* ---------- carving ---------- */
  function carve(pts) {                          // pts: the drawn outline, in pumpkin pixels (0..L)
    if (!built || !imgOk || pts.length < 4) return false;
    let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9, cx = 0, cy = 0;
    pts.forEach(p => { x0 = Math.min(x0, p[0]); y0 = Math.min(y0, p[1]); x1 = Math.max(x1, p[0]); y1 = Math.max(y1, p[1]); cx += p[0]; cy += p[1]; });
    cx /= pts.length; cy /= pts.length;
    if (Math.hypot(x1 - x0, y1 - y0) < L * 0.06) return false;
    const pad = (FLESH_W + RIM_W + 3) * k;
    const bx = Math.floor(x0 - pad), by = Math.floor(y0 - pad), bw = Math.ceil(x1 - x0 + pad * 2), bh = Math.ceil(y1 - y0 + pad * 2);

    /* the piece that will fall: a copy of the pumpkin skin inside the outline */
    const pc = document.createElement('canvas'); pc.width = Math.round(bw * dpr); pc.height = Math.round(bh * dpr);
    const px = pc.getContext('2d'); px.scale(dpr, dpr); px.translate(-bx, -by);
    px.save(); trace(px, pts); px.clip('evenodd'); px.drawImage(main, 0, 0, L, L); px.restore();
    let cnt = 0;
    try { const d = px.getImageData ? pc.getContext('2d').getImageData(0, 0, pc.width, pc.height).data : []; for (let i = 3; i < d.length; i += 12) if (d[i] > 128) cnt++; } catch (e) { cnt = 1e9; }
    if (cnt * 3 < total * 0.004) return false;   // the shape was drawn over nothing (or a sliver): ignore it
    const g = pc.getContext('2d'); g.setTransform(dpr, 0, 0, dpr, -bx * dpr, -by * dpr);
    rim(g, pts);

    /* is it a hole inside the pumpkin (dark inside) or a bite out of its edge (see-through)? */
    let enclosed = true;
    try {
      const md = mainX.getImageData(0, 0, main.width, main.height).data, W = main.width; let on = 0;
      pts.forEach(p => { const X = Math.min(W - 1, Math.max(0, Math.round(p[0] * dpr))), Y = Math.min(W - 1, Math.max(0, Math.round(p[1] * dpr))); if (md[(Y * W + X) * 4 + 3] > 128) on++; });
      enclosed = on / pts.length > 0.95;
    } catch (e) { enclosed = false; }

    if (enclosed && HOLE !== 'transparent') {    // dark inside, only where the pumpkin used to be
      tmpX.save(); tmpX.setTransform(1, 0, 0, 1, 0, 0); tmpX.clearRect(0, 0, tmp.width, tmp.height); tmpX.restore();
      tmpX.save(); trace(tmpX, pts); tmpX.fillStyle = HOLE; tmpX.fill('evenodd');
      tmpX.globalCompositeOperation = 'destination-in'; tmpX.setTransform(1, 0, 0, 1, 0, 0); tmpX.drawImage(main, 0, 0); tmpX.restore();
      innerX.save(); innerX.setTransform(1, 0, 0, 1, 0, 0); innerX.drawImage(tmp, 0, 0); innerX.restore();
    }
    mainX.save(); trace(mainX, pts); mainX.globalCompositeOperation = 'destination-out'; mainX.fill('evenodd'); mainX.restore();
    rim(mainX, pts);                              // flat cut face around the hole

    /* put the falling piece exactly where it was cut out, then let it go */
    pc.className = 'pfall';
    pc.style.cssText = 'left:' + (bx / L * 100) + '%;top:' + (by / L * 100) + '%;width:' + (bw / L * 100) + '%;height:' + (bh / L * 100) + '%;';
    stage.appendChild(pc);
    drop(pc, (cx - bx) / bw, (cy - by) / bh, [(cx / L) - .5, (cy / L) - .5]);

    if (!rm) main.animate([{ transform: 'none' }, { transform: 'translate(' + ((Math.random() - .5) * 5) + 'px,2px) rotate(' + ((Math.random() - .5) * 1.4) + 'deg)', offset: .3 }, { transform: 'none' }], { duration: 360, easing: 'ease-out' });
    return true;
  }

  /* the cut piece pops out a little, tumbles and falls off the bottom of the screen */
  function drop(el, ox, oy, away) {
    if (rm) { el.style.transition = 'opacity .25s'; requestAnimationFrame(() => { el.style.opacity = 0; }); setTimeout(() => el.remove(), 300); return; }
    const S = stage.getBoundingClientRect(), size = S.width, d = Math.hypot(away[0], away[1]) || 1;
    el.style.transformOrigin = (ox * 100) + '% ' + (oy * 100) + '%';
    let x = 0, y = 0, rot = 0;
    let vx = away[0] / d * size * .22 * Math.min(1, d * 3) + (Math.random() - .5) * size * .12;
    let vy = -size * .16 + away[1] / d * size * .1 * Math.min(1, d * 3);
    const gr = size * 3.4, w = (vx >= 0 ? 1 : -1) * (120 + Math.random() * 150);
    const oyAbs = S.top + (parseFloat(el.style.top) / 100 + parseFloat(el.style.height) / 200) * size;
    let last = performance.now();
    (function step(now) {
      const dt = Math.min(.05, (now - last) / 1000); last = now;
      vy += gr * dt; x += vx * dt; y += vy * dt; rot += w * dt;
      el.style.transform = 'translate(' + x + 'px,' + y + 'px) rotate(' + rot + 'deg)';
      if (oyAbs + y > innerHeight + size * .7) { el.remove(); return; }
      requestAnimationFrame(step);
    })(last);
  }

  /* ---------- drawing the shape ---------- */
  let started = false, ready = false, down = null;
  const toLocal = (cx, cy) => { const r = stage.getBoundingClientRect(); return [(cx - r.left) / r.width * L, (cy - r.top) / r.height * L]; };
  const trail = () => {
    const p = down.pts, s = p.map(q => q[0] + ',' + q[1]).join(' ');
    glow.setAttribute('points', s); line.setAttribute('points', s);
    const a = p[0], b = p[p.length - 1];
    closeL.setAttribute('x1', b[0]); closeL.setAttribute('y1', b[1]); closeL.setAttribute('x2', a[0]); closeL.setAttribute('y2', a[1]);
  };
  const trailOn = on => [glow, line, closeL].forEach(l => l.classList.toggle('on', on));

  sec.addEventListener('pointerdown', e => {
    if (!ready || (e.pointerType === 'mouse' && e.button !== 0)) return;
    e.preventDefault();
    down = { pts: [[e.clientX, e.clientY]] }; trail(); trailOn(true);
  });
  window.addEventListener('pointermove', e => {
    if (!down) return;
    const l = down.pts[down.pts.length - 1];
    if (Math.hypot(e.clientX - l[0], e.clientY - l[1]) < 3) return;
    down.pts.push([e.clientX, e.clientY]); trail();
  });
  window.addEventListener('pointerup', () => {
    if (!down) return;
    const d = down; down = null; trailOn(false);
    if (carve(d.pts.map(p => toLocal(p[0], p[1])))) hint.classList.add('hide');
  });
  window.addEventListener('pointercancel', () => { down = null; trailOn(false); });

  /* ---------- the hand-over: prize shown -> wait -> scratch card out, pumpkin in ---------- */
  function start() {
    if (sec.classList.contains('show')) return;
    scratchEl.classList.add('out');
    coinEl.classList.add('gone');
    build();
    sec.classList.add('show');
    setTimeout(() => { ready = true; }, rm ? 0 : 1900);   // carving works once the pumpkin has landed
  }
  function arm() {
    if (started || !scratchEl.classList.contains('cleared')) return;
    started = true;
    setTimeout(start, rm ? 0 : WAIT_MS);
  }
  new MutationObserver(arm).observe(scratchEl, { attributes: true, attributeFilter: ['class'] });
  setInterval(arm, 300);                         // safety net in case the class change is ever missed
  window.startPumpkin = start;                   // for testing: type startPumpkin() in the browser console
})();
